var L = 46, R = W - 18, B = H - 34, T = 18;
var T1 = 4;
function vOf(x) { return 2 + p.c * x * x; }
var vmax = vOf(T1) * 1.15 + 0.001;
function px(x) { return L + (R - L) * (x / T1); }
function py(v) { return B - (B - T) * (v / vmax); }

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, T); ctx.lineTo(L, B); ctx.lineTo(R, B); ctx.stroke();

// rectangles (left endpoint)
var n = Math.round(p.n), dt = T1 / n, sum = 0, i;
var sweep = (t * 0.9) % (n + 1.4);
for (i = 0; i < n; i++) {
  var x0 = i * dt, h = vOf(x0);
  sum += h * dt;
  var lit = (i < sweep);
  ctx.fillStyle = lit ? C.accent : C.faint;
  ctx.globalAlpha = lit ? 0.30 : 0.18;
  ctx.fillRect(px(x0), py(h), px(x0 + dt) - px(x0), B - py(h));
  ctx.globalAlpha = 1;
  ctx.strokeStyle = C.rule;
  ctx.strokeRect(px(x0), py(h), px(x0 + dt) - px(x0), B - py(h));
}

// curve
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (i = 0; i <= 120; i++) {
  var xx = T1 * i / 120;
  i === 0 ? ctx.moveTo(px(xx), py(vOf(xx))) : ctx.lineTo(px(xx), py(vOf(xx)));
}
ctx.stroke();

// labels
ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("v (m/s)", 6, T + 2);
ctx.fillText("t (s)", R - 24, B + 18);
ctx.fillText("0", L - 4, B + 18);
ctx.fillText("4", R - 4, B + 18);
ctx.fillText("area = displacement", px(0.35), py(vOf(T1) * 0.25));

var exact = 2 * T1 + p.c * T1 * T1 * T1 / 3;
out.note = "slices: " + n + "   rectangle sum = " + sum.toFixed(3) +
  " m   exact area = " + exact.toFixed(3) + " m   error = " + (exact - sum).toFixed(3) + " m";

var L = 44, R = W - 16, B = H - 34, T = 26;
var TMAX = 14, VMAX = 15;
function px(x) { return L + (R - L) * (x / TMAX); }
function py(v) { return B - (B - T) * (v / VMAX); }

ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, T); ctx.lineTo(L, B); ctx.lineTo(R, B); ctx.stroke();

// filled regions
ctx.fillStyle = C.accent; ctx.globalAlpha = 0.22;
ctx.beginPath();
ctx.moveTo(px(0), py(0)); ctx.lineTo(px(4), py(12)); ctx.lineTo(px(4), py(0)); ctx.closePath(); ctx.fill();
ctx.beginPath();
ctx.moveTo(px(4), py(0)); ctx.lineTo(px(4), py(12)); ctx.lineTo(px(10), py(12)); ctx.lineTo(px(10), py(0)); ctx.closePath(); ctx.fill();
ctx.beginPath();
ctx.moveTo(px(10), py(0)); ctx.lineTo(px(10), py(12)); ctx.lineTo(px(14), py(0)); ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// dividing lines
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px(4), py(0)); ctx.lineTo(px(4), py(12)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px(10), py(0)); ctx.lineTo(px(10), py(12)); ctx.stroke();
ctx.beginPath(); ctx.moveTo(L, py(12)); ctx.lineTo(px(10), py(12)); ctx.stroke();
ctx.setLineDash([]);

// the curve
ctx.strokeStyle = C.figure; ctx.lineWidth = 2.5;
ctx.beginPath();
ctx.moveTo(px(0), py(0)); ctx.lineTo(px(4), py(12)); ctx.lineTo(px(10), py(12)); ctx.lineTo(px(14), py(0));
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("v (m/s)", 4, T - 10);
ctx.fillText("t (s)", R - 22, B + 20);
ctx.fillText("12", L - 22, py(12) + 4);
ctx.fillText("0", L - 10, B + 4);
ctx.fillText("4", px(4) - 3, B + 18);
ctx.fillText("10", px(10) - 6, B + 18);
ctx.fillText("14", px(14) - 10, B + 18);
ctx.fillText("24 m", px(2.1) - 12, py(4));
ctx.fillText("72 m", px(7) - 14, py(6));
ctx.fillText("24 m", px(11.4) - 10, py(4));
out.note = "total area = 24 + 72 + 24 = 120 m";

var L = 52, R = W - 18, B = H - 40, T = 54;
var XM = 0.30, FM = 500 * 0.30;
function px(x) { return L + (R - L) * (x / XM); }
function py(f) { return B - (B - T) * (f / FM); }

var frac = 0.5 - 0.5 * Math.cos(t * 1.1);
var x = p.xmax * frac;

// shaded work so far
ctx.fillStyle = C.accent; ctx.globalAlpha = 0.28;
ctx.beginPath();
ctx.moveTo(px(0), py(0)); ctx.lineTo(px(x), py(p.k * x)); ctx.lineTo(px(x), py(0)); ctx.closePath(); ctx.fill();
ctx.globalAlpha = 1;

// full triangle outline
ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(px(p.xmax), py(0)); ctx.lineTo(px(p.xmax), py(p.k * p.xmax)); ctx.stroke();
ctx.setLineDash([]);

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(L, T - 30); ctx.lineTo(L, B); ctx.lineTo(R, B); ctx.stroke();

// line F = kx
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(px(0), py(0)); ctx.lineTo(px(p.xmax), py(p.k * p.xmax)); ctx.stroke();

// moving marker
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(px(x), py(p.k * x), 4.5, 0, 6.2832); ctx.fill();

// spring cartoon along the top
var sy = 24, sx0 = L, sx1 = px(x) + 30;
ctx.fillStyle = C.faint; ctx.fillRect(sx0 - 6, sy - 14, 6, 28);
ctx.strokeStyle = C.figure; ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(sx0, sy);
for (var i = 1; i <= 14; i++) {
  ctx.lineTo(sx0 + (sx1 - 12 - sx0) * i / 14, sy + (i % 2 === 0 ? -8 : 8) * (i === 14 ? 0 : 1));
}
ctx.lineTo(sx1 - 12, sy); ctx.stroke();
ctx.fillStyle = C.figure; ctx.fillRect(sx1 - 12, sy - 10, 20, 20);

ctx.fillStyle = C.ink;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.fillText("F (N)", 6, T - 32);
ctx.fillText("x (m)", R - 28, B + 20);
ctx.fillText("0", L - 10, B + 16);
ctx.fillText("F = kx", px(p.xmax) - 50, py(p.k * p.xmax) - 8);
ctx.fillText("work done so far", px(0.02), py(p.k * p.xmax * 0.18));

out.note = "x = " + x.toFixed(3) + " m   F = " + (p.k * x).toFixed(1) +
  " N   W = " + (0.5 * p.k * x * x).toFixed(3) + " J   (full stretch: " +
  (0.5 * p.k * p.xmax * p.xmax).toFixed(3) + " J)";
